_RETRYABLE_YFINANCE_EXCEPTIONS: tuple[type[Exception], ...] = (ConnectionError, TimeoutError, OSError, YFRateLimitError)
_ANALYST_ESTIMATE_SECTIONS: dict[str, tuple[str, str | None, bool]] = {'recommendations': ('recommendations', None, False), 'earnings_estimate': ('earnings_estimate', 'period', False), 'revenue_estimate': ('revenue_estimate', 'period', False), 'eps_trend': ('eps_trend', 'period', False), 'eps_revisions': ('eps_revisions', 'period', False), 'earnings_history': ('earnings_history', 'date', True), 'growth_estimates': ('growth_estimates', 'period', False)}

def _is_retryable_yfinance_error(exc: BaseException) -> bool:
    return isinstance(exc, _RETRYABLE_YFINANCE_EXCEPTIONS)

def _is_rate_limit_error(exc: BaseException) -> bool:
    return isinstance(exc, YFRateLimitError)

def _create_retryable_error_response(action: str, exc: BaseException, details: dict[str, Any]) -> str:
    if _is_rate_limit_error(exc):
        message = f'Rate limit reached while {action}. Try again later.'
    else:
        message = f'Temporary network issue while {action}. Try again later.'
    return create_error_response(message, error_code='NETWORK_ERROR', details={**details, 'exception': str(exc)})

def _select_retryable_exception(exceptions: list[Exception]) -> BaseException:
    rate_limit_exception = next((exc for exc in exceptions if _is_rate_limit_error(exc)), None)
    return rate_limit_exception or exceptions[0]

def _normalize_json_value(value: Any) -> Any:
    """Replace non-finite numeric values recursively so responses remain strict JSON."""
    if isinstance(value, dict):
        return {key: _normalize_json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_normalize_json_value(item) for item in value]
    if isinstance(value, Real) and (not math.isfinite(float(value))):
        return None
    return value

def _dataframe_records(frame: Any, max_rows: int, *, include_index: bool, index_name: str | None=None, sort_descending: bool=False) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    prepared = frame.copy()
    if sort_descending:
        prepared = prepared.sort_index(ascending=False)
    if include_index:
        if index_name is not None:
            prepared.index.name = index_name
        prepared = prepared.reset_index()
    total_rows = len(prepared)
    limited = prepared if max_rows == 0 else prepared.head(max_rows)
    limited = limited.astype(object).where(limited.notna(), None)
    records = _normalize_json_value(limited.to_dict(orient='records'))
    return (records, {'total_rows': total_rows, 'returned_rows': len(records), 'truncated': len(records) < total_rows})

def _validate_sections(sections: list[str] | None, valid_sections: set[str], *, max_rows: int) -> tuple[list[str] | None, str | None]:
    if max_rows < 0:
        return (None, create_error_response('max_rows must be greater than or equal to 0.', error_code='INVALID_PARAMS', details={'max_rows': max_rows}))
    if sections is not None and (not sections):
        return (None, create_error_response('sections must include at least one section when provided.', error_code='INVALID_PARAMS', details={'sections': sections, 'valid_sections': sorted(valid_sections)}))
    selected = sorted(valid_sections) if sections is None else list(dict.fromkeys(sections))
    invalid = sorted(set(selected).difference(valid_sections))
    if invalid:
        return (None, create_error_response('One or more requested sections are invalid.', error_code='INVALID_PARAMS', details={'invalid_sections': invalid, 'valid_sections': sorted(valid_sections)}))
    return (selected, None)

def _section_fetch_error_response(symbol: str, subject: str, selected_sections: list[str], fetch_errors: list[tuple[str, Exception]]) -> str:
    retryable = [exc for _, exc in fetch_errors if _is_retryable_yfinance_error(exc)]
    failed_sections = [section for section, _ in fetch_errors]
    details: dict[str, Any] = {'symbol': symbol, 'requested_sections': selected_sections, 'failed_sections': failed_sections}
    if retryable:
        return _create_retryable_error_response(f"fetching {subject} for '{symbol}'", _select_retryable_exception(retryable), details)
    details['exception'] = str(fetch_errors[0][1])
    return create_error_response(f"Failed to fetch {subject} for '{symbol}'.", error_code='API_ERROR', details=details)

@mcp.tool(name='yfinance_get_analyst_estimates', annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
async def get_analyst_estimates(symbol: Annotated[str, Field(description="Stock ticker symbol (e.g., 'AAPL', 'GOOGL', 'MSFT')")], sections: Annotated[list[str] | None, Field(description='Optional analyst sections: recommendations, earnings_estimate, revenue_estimate, eps_trend, eps_revisions, earnings_history, and growth_estimates. Omit to return all sections.')]=None, max_rows: Annotated[int, Field(description='Maximum rows per section. Use 0 to return all rows.')]=12) -> str:
    """Fetch consensus estimates, EPS/revenue trends, revisions, recommendations, and earnings history."""
    selected_sections, validation_error = _validate_sections(sections, set(_ANALYST_ESTIMATE_SECTIONS), max_rows=max_rows)
    if validation_error is not None:
        return validation_error
    assert selected_sections is not None
    try:
        ticker = await asyncio.to_thread(yf.Ticker, symbol)
    except _RETRYABLE_YFINANCE_EXCEPTIONS as exc:
        return _create_retryable_error_response(f"fetching analyst estimates for '{symbol}'", exc, {'symbol': symbol})
    except Exception as exc:
        return create_error_response(f"Failed to fetch analyst estimates for '{symbol}'.", error_code='API_ERROR', details={'symbol': symbol, 'exception': str(exc)})
    response: dict[str, Any] = {}
    section_metadata: dict[str, Any] = {}
    unavailable_sections: list[str] = []
    fetch_errors: list[tuple[str, Exception]] = []
    for section in selected_sections:
        attribute, index_name, sort_descending = _ANALYST_ESTIMATE_SECTIONS[section]
        try:
            frame = await asyncio.to_thread(lambda attribute=attribute: getattr(ticker, attribute))
            if frame is None or frame.empty:
                unavailable_sections.append(section)
                continue
            records, metadata = _dataframe_records(frame, max_rows, include_index=index_name is not None, index_name=index_name, sort_descending=sort_descending)
            response[section] = records
            section_metadata[section] = metadata
        except Exception as exc:
            fetch_errors.append((section, exc))
    if not response:
        if fetch_errors:
            return _section_fetch_error_response(symbol, 'analyst estimates', selected_sections, fetch_errors)
        return create_error_response(f"No analyst estimates available for '{symbol}'.", error_code='NO_DATA', details={'symbol': symbol, 'requested_sections': selected_sections})
    response['_metadata'] = {'symbol': symbol, 'max_rows': max_rows, 'requested_sections': selected_sections, 'sections': section_metadata, 'unavailable_sections': unavailable_sections, 'failed_sections': [section for section, _ in fetch_errors]}
    return dump_json(response)

